    else if (!strcmp(argv[i], "--json")) o->json = 1;
    else if (!strcmp(argv[i], "--limit") && i + 1 < argc) o->limit = (int)parse_count("--limit", argv[++i]);
    else if (!strncmp(argv[i], "--", 2)) die("unknown option %s", argv[i]);
    else o->words[o->nwords++] = argv[i];
  }
}

